export function saveRule(source,data){const s=clone(source);req(data,["name","field","operator","value","actionType","actionValue"]);const old=s.rules.find(x=>x.id===data.id),x={...old,...data,id:old?.id||uid("RULE"),priority:num(data.priority)||100,active:data.active!==false,createdAt:old?.createdAt||now(),updatedAt:now()};if(old)s.rules[s.rules.indexOf(old)]=x;else s.rules.unshift(x);log(s,old?"Bank rule updated":"Bank rule created","Bank Rule",x.id);return{state:s,record:x}}function ruleMatch(r,t){if(!r.active)return false;const a=r.field==="amount"?t.amount:String(t[r.field]||"").toLowerCase(),v=r.field==="amount"?num(r.value):String(r.value||"").toLowerCase();if(r.operator==="contains")return String(a).includes(String(v));if(r.operator==="starts with")return String(a).startsWith(String(v));if(r.operator==="ends with")return String(a).endsWith(String(v));if(r.operator==="equals")return a===v;if(r.operator==="greater")return a>v;if(r.operator==="less")return a<v;if(r.operator==="between")return a>=v&&a<=num(r.value2);return false}export function previewRule(s,id){const r=s.rules.find(x=>x.id===id);return s.transactions.filter(t=>ruleMatch(r,t))}export function applyRule(source,id,transactionIds){const s=clone(source),r=s.rules.find(x=>x.id===id),changed=[];for(const t of s.transactions.filter(x=>transactionIds.includes(x.id)&&ruleMatch(r,x))){t.ruleUndo={category:t.category,customerId:t.customerId,supplierId:t.supplierId,notes:t.notes};if(r.actionType==="category")t.category=r.actionValue;if(r.actionType==="note")t.notes=[t.notes,r.actionValue].filter(Boolean).join("; ");if(r.actionType==="customer")t.customerId=r.actionValue;if(r.actionType==="supplier")t.supplierId=r.actionValue;t.ruleId=r.id;changed.push(t.id)}log(s,"Bank rule applied","Bank Rule",id,{transactions:changed});return{state:s,changed}}
