export const REPORTS=["Account Balance Summary","Bank Book","Cash Book","Receipts Register","Payments Register","Bank Transaction Register","Unreconciled Transactions","Reconciliation Summary","Account Transfers","Bank Charges","Interest Income","Customer Collections","Supplier Payments","Outstanding Invoice Collections","Outstanding Supplier Payments","Cash Flow","Daily Cash Closing","Cash Variance","Cheque Status","Credit Card Summary","UPI/Wallet Summary","Marketplace Settlements"];export function reportRows(s,t){const active=s.transactions.filter(x=>x.status!=="Reversed"),map={"Account Balance Summary":s.accounts.map(x=>({...x,currentBalance:accountBalance(s,x.id)})),"Bank Book":active.filter(x=>!["Cash Account","Petty Cash"].includes(s.accounts.find(a=>a.id===x.accountId)?.type)),"Cash Book":active.filter(x=>["Cash Account","Petty Cash"].includes(s.accounts.find(a=>a.id===x.accountId)?.type)),"Receipts Register":active.filter(x=>x.direction==="In"),"Payments Register":active.filter(x=>x.direction==="Out"),"Bank Transaction Register":active,"Unreconciled Transactions":active.filter(x=>x.reconciliationStatus!=="Reconciled"),"Reconciliation Summary":s.reconciliations,"Account Transfers":s.transfers,"Bank Charges":active.filter(x=>x.category==="Bank Charge"),"Interest Income":active.filter(x=>x.category==="Interest Income"),"Customer Collections":active.filter(x=>x.category==="Customer Payment"),"Supplier Payments":active.filter(x=>x.category==="Supplier Payment"),"Outstanding Invoice Collections":[],"Outstanding Supplier Payments":[],"Cash Flow":active,"Daily Cash Closing":s.cashClosings,"Cash Variance":s.cashClosings.filter(x=>x.difference),"Cheque Status":s.cheques,"Credit Card Summary":s.accounts.filter(x=>x.type==="Credit Card"),"UPI/Wallet Summary":s.accounts.filter(x=>["UPI Account","Digital Wallet"].includes(x.type)),"Marketplace Settlements":s.integration.marketplace};return map[t]||[]}export function toCsv(rows){if(!rows.length)return"";const ks=[...new Set(rows.flatMap(Object.keys))].filter(k=>typeof rows[0]?.[k]!=="object"&&!/accountNumber/i.test(k));const c=v=>`"${String(v??"").replaceAll('"','""')}"`;return[ks.map(c).join(","),...rows.map(r=>ks.map(k=>c(r[k])).join(","))].join("\r\n")}
